const userId = $json.jwtPayload?.userId;
if (!userId) return [{ json: { __error: true, __code: 401, __message: 'Token sin userId' } }];
const q = $json.query || {};
const from = (q.from || q.startingDateAndTime || '').toString().trim();
const to = (q.to || q.endingDateAndTime || '').toString().trim();
if (!from || !to) {
  return [{ json: { __error: true, __code: 400, __message: 'from y to son requeridos' } }];
}
// Uno o el otro: con calendario, todo lo de ese calendario; sin calendario, lo
// asignado al sujeto del token. El tecnico NO se acepta por parametro — sale
// siempre del token, para que no haya forma de que el filtro se caiga.
const calendarId = (q.calendar_source_id || '').toString().trim();

return [{ json: {
  user_id: String(userId),
  payload: JSON.stringify({ from, to, calendar_source_id: /^\d+$/.test(calendarId) ? calendarId : '' }),
} }];

// Arma el sobre { code, message, data, meta }. Un resultado vacío en una
// operación de escritura significa que el WHERE de guarda no dejó pasar:
// es un 409/404, no un 500.
//
// El filtro descarta el item vacio que emite el nodo de Postgres cuando la
// consulta no devuelve filas (lleva alwaysOutputData para que el flujo llegue a
// responder). Sin el, ese {} se colaria como si fuera una fila real: un detalle
// de orden vacio en vez de un 404, o un listado con un elemento fantasma.
const rows = $input.all()
  .map((i) => i.json)
  .filter((r) => r && typeof r === 'object' && Object.keys(r).length > 0);

// Sin tareas no es un error: el técnico puede tener el día libre.
return [{ json: { __data: rows } }];
